{
  "name": "Mapa de Riesgo Vial",
  "description": "Una aplicación web para visualizar y gestionar riesgos viales en rutas de transporte de pasajeros en San Rafael, Mendoza. Permite cargar rutas a través de KML, marcar y tipificar riesgos en el mapa, y generar reportes de riesgo por recorrido."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

import React, { useState, useEffect, useCallback } from 'react';
import { MapContainer, TileLayer, Marker, Popup, Polyline, useMapEvents, Circle } from 'react-leaflet';
import { LatLngExpression, LatLng, Icon } from 'leaflet';
import { pointToLineDistance } from '@turf/turf';
import { toGeoJSON } from '@tmcw/togeojson';
import { v4 as uuidv4 } from 'uuid';

import type { Route, Risk, RiskType, Position, GeoJSONFeature, GeoJSONLineString } from './types';
import { Panel } from './components/Panel';
import { AddRiskModal } from './components/AddRiskModal';
import { MapClickHandler } from './components/MapClickHandler';

// Default map center: San Rafael, Mendoza, Argentina
const SAN_RAFAEL_CENTER: LatLngExpression = [-34.6175, -68.335];

const createRiskIcon = (color: string) => {
    const iconHtml = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="${color}" width="32" height="32"><path d="M12 2C8.13 2 5 5.13 5 9c0 5.25 7 13 7 13s7-7.75 7-13c0-3.87-3.13-7-7-7zm0 9.5c-1.38 0-2.5-1.12-2.5-2.5s1.12-2.5 2.5-2.5 2.5 1.12 2.5 2.5-1.12 2.5-2.5 2.5z"/></svg>`;
    return new Icon({
        iconUrl: `data:image/svg+xml;base64,${btoa(iconHtml)}`,
        iconSize: [32, 32],
        iconAnchor: [16, 32],
        popupAnchor: [0, -32]
    });
};


const App: React.FC = () => {
    const [riskTypes, setRiskTypes] = useState<RiskType[]>(() => {
        const saved = localStorage.getItem('riskTypes');
        return saved ? JSON.parse(saved) : [
            { id: '1', name: 'Escuela', color: '#3b82f6' },
            { id: '2', name: 'Hospital', color: '#ef4444' },
            { id: '3', name: 'Cruce Peligroso', color: '#f97316' },
            { id: '4', name: 'Contingencia Climática', color: '#8b5cf6' },
            { id: '5', name: 'Accidente Histórico', color: '#eab308' },
        ];
    });

    const [routes, setRoutes] = useState<Route[]>(() => JSON.parse(localStorage.getItem('routes') || '[]'));
    const [risks, setRisks] = useState<Risk[]>(() => JSON.parse(localStorage.getItem('risks') || '[]'));
    const [proximityDistance, setProximityDistance] = useState<number>(() => Number(localStorage.getItem('proximityDistance')) || 50); // in meters
    const [isAddRiskModalOpen, setIsAddRiskModalOpen] = useState<boolean>(false);
    const [newRiskPosition, setNewRiskPosition] = useState<Position | null>(null);

    useEffect(() => {
        localStorage.setItem('riskTypes', JSON.stringify(riskTypes));
    }, [riskTypes]);

    useEffect(() => {
        localStorage.setItem('routes', JSON.stringify(routes));
    }, [routes]);

    useEffect(() => {
        localStorage.setItem('risks', JSON.stringify(risks));
    }, [risks]);

    useEffect(() => {
        localStorage.setItem('proximityDistance', proximityDistance.toString());
    }, [proximityDistance]);

    const findAssociatedRouteIds = useCallback((position: Position): string[] => {
        const associatedIds: string[] = [];
        const riskPoint = [position.lng, position.lat];

        routes.forEach(route => {
            if (route.geoJson) {
                const features = route.geoJson.features.filter(
                    (feature): feature is GeoJSONFeature<GeoJSONLineString> => feature.geometry.type === 'LineString'
                );

                for (const feature of features) {
                    const distance = pointToLineDistance(riskPoint, feature.geometry.coordinates, { units: 'meters' });
                    if (distance <= proximityDistance) {
                        associatedIds.push(route.id);
                        break; // A route is associated if any of its segments are close
                    }
                }
            }
        });
        return associatedIds;
    }, [routes, proximityDistance]);

    const handleMapClick = (latlng: LatLng) => {
        setNewRiskPosition({ lat: latlng.lat, lng: latlng.lng });
        setIsAddRiskModalOpen(true);
    };

    const handleAddRisk = (riskTypeId: string, description: string) => {
        if (newRiskPosition && riskTypeId) {
            const newRisk: Risk = {
                id: uuidv4(),
                position: newRiskPosition,
                riskTypeId: riskTypeId,
                description,
                associatedRouteIds: findAssociatedRouteIds(newRiskPosition),
            };
            setRisks(prev => [...prev, newRisk]);
            setIsAddRiskModalOpen(false);
            setNewRiskPosition(null);
        }
    };

    const handleAddRoute = (name: string, origin: string, destination: string, kmlFile: File) => {
        const reader = new FileReader();
        reader.onload = (event) => {
            try {
                const kmlContent = event.target?.result as string;
                const dom = new DOMParser().parseFromString(kmlContent, 'application/xml');
                const geoJson = toGeoJSON.kml(dom);

                const newRoute: Route = {
                    id: uuidv4(),
                    name,
                    origin,
                    destination,
                    geoJson,
                };
                setRoutes(prev => [...prev, newRoute]);

                // After adding a new route, check existing risks
                setRisks(prevRisks => prevRisks.map(risk => ({
                    ...risk,
                    associatedRouteIds: findAssociatedRouteIds(risk.position)
                })));

            } catch (error) {
                console.error("Error parsing KML file:", error);
                alert("Error al procesar el archivo KML. Por favor, asegúrese de que sea un archivo válido.");
            }
        };
        reader.readAsText(kmlFile);
    };

    const getRiskType = (id: string): RiskType | undefined => riskTypes.find(rt => rt.id === id);

    return (
        <div className="flex h-screen w-screen bg-gray-100 font-sans">
            <Panel
                riskTypes={riskTypes}
                setRiskTypes={setRiskTypes}
                routes={routes}
                setRoutes={setRoutes}
                risks={risks}
                setRisks={setRisks}
                proximityDistance={proximityDistance}
                setProximityDistance={setProximityDistance}
                onAddRoute={handleAddRoute}
                getRiskType={getRiskType}
            />
            <main className="flex-1 h-full relative">
                 <MapContainer center={SAN_RAFAEL_CENTER} zoom={13} style={{ height: '100%', width: '100%' }} className="z-0">
                    <TileLayer
                        url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
                        attribution='&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'
                    />

                    <MapClickHandler onMapClick={handleMapClick} />

                    {routes.map(route => {
                        const path: LatLngExpression[][] = [];
                        if (route.geoJson) {
                            route.geoJson.features.forEach(feature => {
                                if (feature.geometry.type === 'LineString') {
                                    path.push(feature.geometry.coordinates.map(([lng, lat]) => [lat, lng]));
                                }
                            });
                        }
                        return <Polyline key={route.id} positions={path} color="#0284c7" weight={5} />;
                    })}

                    {risks.map(risk => {
                        const riskType = getRiskType(risk.riskTypeId);
                        if (!riskType) return null;

                        const icon = createRiskIcon(riskType.color);

                        const associatedRoutes = routes.filter(r => risk.associatedRouteIds.includes(r.id));

                        return (
                             <Marker key={risk.id} position={[risk.position.lat, risk.position.lng]} icon={icon}>
                                <Popup>
                                    <div className="font-bold text-lg" style={{ color: riskType.color }}>{riskType.name}</div>
                                    <p className="text-gray-700">{risk.description}</p>
                                    {associatedRoutes.length > 0 && (
                                        <div className="mt-2 pt-2 border-t">
                                            <h4 className="font-semibold text-sm text-gray-800">Recorridos Afectados:</h4>
                                            <ul className="list-disc list-inside text-xs text-gray-600">
                                                {associatedRoutes.map(r => <li key={r.id}>{r.name}</li>)}
                                            </ul>
                                        </div>
                                    )}
                                </Popup>
                            </Marker>
                        )
                    })}

                    {newRiskPosition && (
                         <Circle center={[newRiskPosition.lat, newRiskPosition.lng]} radius={proximityDistance} color="#fb923c" fillOpacity={0.2} />
                    )}

                </MapContainer>
            </main>

            {isAddRiskModalOpen && newRiskPosition && (
                <AddRiskModal
                    riskTypes={riskTypes}
                    onClose={() => setIsAddRiskModalOpen(false)}
                    onAddRisk={handleAddRisk}
                />
            )}
        </div>
    );
};

export default App;

export interface Position {
    lat: number;
    lng: number;
}

export interface RiskType {
    id: string;
    name: string;
    color: string;
}

export interface Risk {
    id: string;
    position: Position;
    riskTypeId: string;
    description: string;
    associatedRouteIds: string[];
}

export interface Route {
    id: string;
    name: string;
    origin: string;
    destination: string;
    geoJson: GeoJSON.FeatureCollection | null;
}

// Simplified GeoJSON types for our use case
export interface GeoJSONPoint {
    type: 'Point';
    coordinates: [number, number];
}

export interface GeoJSONLineString {
    type: 'LineString';
    coordinates: [number, number][];
}

export interface GeoJSONFeature<T extends GeoJSONPoint | GeoJSONLineString> {
    type: 'Feature';
    geometry: T;
    properties: Record<string, any>;
}

export interface GeoJSONFeatureCollection {
    type: 'FeatureCollection';
    features: GeoJSONFeature<any>[];
}

import React, { useState } from 'react';
import type { RiskType, Route, Risk } from '../types';
import { RouteManager } from './RouteManager';
import { RiskTypeManager } from './RiskTypeManager';
import { ReportViewer } from './ReportViewer';
import { Settings } from './Settings';
import { Map, MapPin, AlertTriangle, FileBarChart, Settings as SettingsIcon } from 'lucide-react';

type Tab = 'routes' | 'riskTypes' | 'reports' | 'settings';

interface PanelProps {
    riskTypes: RiskType[];
    setRiskTypes: React.Dispatch<React.SetStateAction<RiskType[]>>;
    routes: Route[];
    setRoutes: React.Dispatch<React.SetStateAction<Route[]>>;
    risks: Risk[];
    setRisks: React.Dispatch<React.SetStateAction<Risk[]>>;
    proximityDistance: number;
    setProximityDistance: React.Dispatch<React.SetStateAction<number>>;
    onAddRoute: (name: string, origin: string, destination: string, kmlFile: File) => void;
    getRiskType: (id: string) => RiskType | undefined;
}

export const Panel: React.FC<PanelProps> = ({
    riskTypes,
    setRiskTypes,
    routes,
    setRoutes,
    risks,
    setRisks,
    proximityDistance,
    setProximityDistance,
    onAddRoute,
    getRiskType
}) => {
    const [activeTab, setActiveTab] = useState<Tab>('routes');

    const renderTabContent = () => {
        switch (activeTab) {
            case 'routes':
                return <RouteManager routes={routes} onAddRoute={onAddRoute} setRoutes={setRoutes} />;
            case 'riskTypes':
                return <RiskTypeManager riskTypes={riskTypes} setRiskTypes={setRiskTypes} />;
            case 'reports':
                return <ReportViewer routes={routes} risks={risks} getRiskType={getRiskType} />;
            case 'settings':
                return <Settings proximityDistance={proximityDistance} setProximityDistance={setProximityDistance} />;
            default:
                return null;
        }
    };

    const TabButton: React.FC<{ tabName: Tab; icon: React.ReactNode; label: string }> = ({ tabName, icon, label }) => (
        <button
            onClick={() => setActiveTab(tabName)}
            className={`flex flex-col items-center justify-center p-2 w-full text-xs transition-colors duration-200 ${
                activeTab === tabName ? 'bg-sky-600 text-white' : 'text-gray-300 hover:bg-sky-800 hover:text-white'
            }`}
            title={label}
        >
            {icon}
            <span className="mt-1">{label}</span>
        </button>
    );

    return (
        <aside className="w-[400px] h-full flex bg-gray-800 text-white shadow-lg z-10">
            <div className="w-20 bg-gray-900 flex flex-col items-center py-4 space-y-4">
                 <div className="flex items-center text-sky-400 mb-4">
                    <Map size={32} />
                </div>
                <TabButton tabName="routes" icon={<MapPin size={24} />} label="Recorridos" />
                <TabButton tabName="riskTypes" icon={<AlertTriangle size={24} />} label="Riesgos" />
                <TabButton tabName="reports" icon={<FileBarChart size={24} />} label="Reportes" />
                <TabButton tabName="settings" icon={<SettingsIcon size={24} />} label="Ajustes" />
            </div>
            <div className="flex-1 p-4 overflow-y-auto">
                {renderTabContent()}
            </div>
        </aside>
    );
};

import React, { useState } from 'react';
import type { Route } from '../types';
import { AddRouteModal } from './AddRouteModal';
import { MapPin, PlusCircle, Trash2 } from 'lucide-react';

interface RouteManagerProps {
    routes: Route[];
    setRoutes: React.Dispatch<React.SetStateAction<Route[]>>;
    onAddRoute: (name: string, origin: string, destination: string, kmlFile: File) => void;
}

export const RouteManager: React.FC<RouteManagerProps> = ({ routes, onAddRoute, setRoutes }) => {
    const [isModalOpen, setIsModalOpen] = useState(false);

    const deleteRoute = (id: string) => {
        if(window.confirm("¿Está seguro que desea eliminar este recorrido?")) {
            setRoutes(routes.filter(route => route.id !== id));
        }
    };

    return (
        <div>
            <div className="flex justify-between items-center mb-4">
                <h2 className="text-xl font-bold text-sky-300">Gestión de Recorridos</h2>
                <button
                    onClick={() => setIsModalOpen(true)}
                    className="flex items-center bg-sky-500 hover:bg-sky-600 text-white font-bold py-2 px-3 rounded-lg transition-colors duration-200 text-sm"
                >
                    <PlusCircle size={18} className="mr-2" />
                    Nuevo
                </button>
            </div>
            <div className="space-y-3">
                {routes.length > 0 ? routes.map(route => (
                    <div key={route.id} className="bg-gray-700 p-3 rounded-lg flex justify-between items-center">
                        <div>
                            <p className="font-semibold text-white">{route.name}</p>
                            <p className="text-xs text-gray-400">{route.origin} &rarr; {route.destination}</p>
                        </div>
                        <button onClick={() => deleteRoute(route.id)} className="text-red-400 hover:text-red-600 p-1">
                            <Trash2 size={18} />
                        </button>
                    </div>
                )) : (
                    <div className="text-center py-8 px-4 bg-gray-700 rounded-lg">
                        <MapPin size={40} className="mx-auto text-gray-500" />
                        <p className="mt-2 text-gray-400">No hay recorridos cargados.</p>
                        <p className="text-xs text-gray-500">Agregue uno para comenzar.</p>
                    </div>
                )}
            </div>
            {isModalOpen && (
                <AddRouteModal
                    onClose={() => setIsModalOpen(false)}
                    onAddRoute={onAddRoute}
                />
            )}
        </div>
    );
};

import React, { useState } from 'react';
import type { RiskType } from '../types';
import { v4 as uuidv4 } from 'uuid';
import { AlertTriangle, PlusCircle, Trash2, Edit } from 'lucide-react';


interface RiskTypeManagerProps {
    riskTypes: RiskType[];
    setRiskTypes: React.Dispatch<React.SetStateAction<RiskType[]>>;
}

export const RiskTypeManager: React.FC<RiskTypeManagerProps> = ({ riskTypes, setRiskTypes }) => {
    const [newTypeName, setNewTypeName] = useState('');
    const [newTypeColor, setNewTypeColor] = useState('#ffffff');
    const [editingType, setEditingType] = useState<RiskType | null>(null);

    const handleAddOrUpdate = () => {
        if (!newTypeName.trim()) return;

        if (editingType) {
            setRiskTypes(riskTypes.map(rt => rt.id === editingType.id ? { ...rt, name: newTypeName, color: newTypeColor } : rt));
            setEditingType(null);
        } else {
            const newType: RiskType = {
                id: uuidv4(),
                name: newTypeName,
                color: newTypeColor,
            };
            setRiskTypes([...riskTypes, newType]);
        }
        setNewTypeName('');
        setNewTypeColor('#ffffff');
    };

    const handleEdit = (riskType: RiskType) => {
        setEditingType(riskType);
        setNewTypeName(riskType.name);
        setNewTypeColor(riskType.color);
    };

    const handleDelete = (id: string) => {
        if(window.confirm("¿Está seguro que desea eliminar este tipo de riesgo?")) {
            setRiskTypes(riskTypes.filter(rt => rt.id !== id));
        }
    };

    const cancelEdit = () => {
        setEditingType(null);
        setNewTypeName('');
        setNewTypeColor('#ffffff');
    }

    return (
        <div>
            <h2 className="text-xl font-bold mb-4 text-sky-300">Tipos de Riesgo</h2>
            <div className="bg-gray-700 p-4 rounded-lg mb-4">
                <h3 className="font-semibold mb-2">{editingType ? 'Editar Tipo de Riesgo' : 'Agregar Nuevo Tipo'}</h3>
                <div className="flex items-center space-x-2">
                    <input
                        type="text"
                        value={newTypeName}
                        onChange={(e) => setNewTypeName(e.target.value)}
                        placeholder="Nombre del riesgo"
                        className="flex-grow bg-gray-800 text-white p-2 rounded-md border border-gray-600 focus:ring-sky-500 focus:border-sky-500"
                    />
                    <input
                        type="color"
                        value={newTypeColor}
                        onChange={(e) => setNewTypeColor(e.target.value)}
                        className="p-1 h-10 w-10 block bg-gray-800 border border-gray-600 cursor-pointer rounded-lg disabled:opacity-50 disabled:pointer-events-none"
                    />
                </div>
                <div className="flex justify-end space-x-2 mt-3">
                    {editingType && <button onClick={cancelEdit} className="bg-gray-500 hover:bg-gray-600 text-white font-bold py-2 px-3 rounded-lg text-sm">Cancelar</button>}
                    <button onClick={handleAddOrUpdate} className="bg-sky-500 hover:bg-sky-600 text-white font-bold py-2 px-3 rounded-lg text-sm">
                        {editingType ? 'Actualizar' : 'Agregar'}
                    </button>
                </div>
            </div>

            <div className="space-y-2">
                {riskTypes.length > 0 ? riskTypes.map(rt => (
                    <div key={rt.id} className="bg-gray-700 p-3 rounded-lg flex items-center justify-between">
                        <div className="flex items-center">
                            <div className="w-4 h-4 rounded-full mr-3" style={{ backgroundColor: rt.color }}></div>
                            <span>{rt.name}</span>
                        </div>
                        <div className="flex space-x-2">
                            <button onClick={() => handleEdit(rt)} className="text-yellow-400 hover:text-yellow-500 p-1"><Edit size={16} /></button>
                            <button onClick={() => handleDelete(rt.id)} className="text-red-400 hover:text-red-500 p-1"><Trash2 size={16} /></button>
                        </div>
                    </div>
                )) : (
                    <div className="text-center py-8 px-4 bg-gray-700 rounded-lg">
                        <AlertTriangle size={40} className="mx-auto text-gray-500" />
                        <p className="mt-2 text-gray-400">No hay tipos de riesgo definidos.</p>
                    </div>
                )}
            </div>
        </div>
    );
};

import React, { useState, useMemo } from 'react';
import type { Route, Risk, RiskType } from '../types';
import { FileBarChart, Search } from 'lucide-react';

interface ReportViewerProps {
    routes: Route[];
    risks: Risk[];
    getRiskType: (id: string) => RiskType | undefined;
}

export const ReportViewer: React.FC<ReportViewerProps> = ({ routes, risks, getRiskType }) => {
    const [selectedRouteId, setSelectedRouteId] = useState<string>('');

    const selectedRouteRisks = useMemo(() => {
        if (!selectedRouteId) return [];
        return risks.filter(risk => risk.associatedRouteIds.includes(selectedRouteId));
    }, [selectedRouteId, risks]);

    const selectedRoute = useMemo(() => {
        return routes.find(r => r.id === selectedRouteId);
    }, [selectedRouteId, routes]);


    return (
        <div>
            <h2 className="text-xl font-bold mb-4 text-sky-300">Reporte de Riesgos por Recorrido</h2>

            <div className="mb-4">
                <label htmlFor="route-select" className="block text-sm font-medium text-gray-300 mb-1">Seleccionar Recorrido</label>
                <select
                    id="route-select"
                    value={selectedRouteId}
                    onChange={(e) => setSelectedRouteId(e.target.value)}
                    className="w-full bg-gray-700 text-white p-2 rounded-md border border-gray-600 focus:ring-sky-500 focus:border-sky-500"
                >
                    <option value="">-- Elija un recorrido --</option>
                    {routes.map(route => (
                        <option key={route.id} value={route.id}>{route.name}</option>
                    ))}
                </select>
            </div>

            {selectedRoute ? (
                 <div className="bg-gray-700 p-4 rounded-lg">
                    <h3 className="text-lg font-semibold text-white mb-1">{selectedRoute.name}</h3>
                    <p className="text-sm text-gray-400 mb-3">{selectedRoute.origin} &rarr; {selectedRoute.destination}</p>

                    <div className="border-t border-gray-600 pt-3">
                        <h4 className="font-bold text-sky-400 mb-2">Riesgos Asociados ({selectedRouteRisks.length})</h4>
                        {selectedRouteRisks.length > 0 ? (
                            <ul className="space-y-2">
                                {selectedRouteRisks.map(risk => {
                                    const riskType = getRiskType(risk.riskTypeId);
                                    return (
                                        <li key={risk.id} className="bg-gray-800 p-3 rounded-md">
                                            <div className="flex items-center mb-1">
                                                <div className="w-3 h-3 rounded-full mr-2" style={{ backgroundColor: riskType?.color || '#fff' }}></div>
                                                <span className="font-semibold text-white">{riskType?.name || 'Desconocido'}</span>
                                            </div>
                                            <p className="text-sm text-gray-300 pl-5">{risk.description}</p>
                                        </li>
                                    );
                                })}
                            </ul>
                        ) : (
                            <p className="text-gray-400">No se encontraron riesgos para este recorrido.</p>
                        )}
                    </div>
                </div>
            ) : (
                <div className="text-center py-10 px-4 bg-gray-700 rounded-lg">
                    <FileBarChart size={40} className="mx-auto text-gray-500" />
                    <p className="mt-2 text-gray-400">Seleccione un recorrido para ver su reporte de riesgos.</p>
                </div>
            )}
        </div>
    );
};

import React from 'react';
import { Settings as SettingsIcon } from 'lucide-react';

interface SettingsProps {
    proximityDistance: number;
    setProximityDistance: React.Dispatch<React.SetStateAction<number>>;
}

export const Settings: React.FC<SettingsProps> = ({ proximityDistance, setProximityDistance }) => {
    return (
        <div>
            <h2 className="text-xl font-bold mb-4 text-sky-300">Ajustes Generales</h2>
            <div className="bg-gray-700 p-4 rounded-lg">
                <div className="mb-4">
                    <label htmlFor="proximity-distance" className="block text-sm font-medium text-gray-300 mb-2">
                        Distancia de Proximidad de Riesgo
                    </label>
                    <div className="flex items-center space-x-3">
                         <input
                            type="range"
                            id="proximity-distance"
                            min="10"
                            max="500"
                            step="10"
                            value={proximityDistance}
                            onChange={(e) => setProximityDistance(Number(e.target.value))}
                            className="w-full h-2 bg-gray-600 rounded-lg appearance-none cursor-pointer"
                        />
                        <span className="text-sky-400 font-semibold w-20 text-center">{proximityDistance} mts.</span>
                    </div>
                    <p className="text-xs text-gray-400 mt-2">
                        Define el radio alrededor de un punto de riesgo para asociarlo automáticamente a un recorrido cercano.
                    </p>
                </div>
            </div>
        </div>
    );
};

import React, { useState } from 'react';
import type { RiskType } from '../types';
import { X } from 'lucide-react';

interface AddRiskModalProps {
    riskTypes: RiskType[];
    onClose: () => void;
    onAddRisk: (riskTypeId: string, description: string) => void;
}

